// Dynamic Attachment File Renamer & Year/Month Folder Path Generator
return $input.all().map((item) => {
  const j = item.json || {};
  const rawDate = j.date || new Date().toISOString();
  const yyyyMmDd = String(rawDate).slice(0, 10);
  const yyyy = yyyyMmDd.slice(0, 4) || '2027';
  const mm = yyyyMmDd.slice(5, 7) || '11';

  const fromRaw = String(j.from || 'Stripe Billing <billing@stripe.com>');
  const vendorClean = fromRaw.split('<')[0].replace(/[^a-zA-Z0-9_-]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '') || 'Vendor';

  const origFile = j.attachment || (item.binary && item.binary.attachment_0 && item.binary.attachment_0.fileName) || 'Settlement_Report.pdf';
  const cleanFileName = origFile.startsWith('202') ? origFile : `${yyyyMmDd}_${vendorClean}_${origFile}`;

  return {
    json: {
      Date_Saved: yyyyMmDd,
      Sender_Vendor: fromRaw.replace(/"/g, ''),
      Clean_File_Name: cleanFileName,
      Archive_Folder: `/${yyyy}_Archive/${mm}/`,
      Drive_Status: '✓ Uploaded to Google Drive & Indexed'
    },
    binary: item.binary
  };
});
